//! The app icon at runtime: the window icon (title bar, taskbar and
//! app switcher on Windows and X11) and, on macOS when not running from
//! `Shift.app`, the Dock icon. Bundles and packages carry their own copies
//! (`.icns`, hicolor PNGs, `.ico`), all generated by `packaging/gen-icon.py`.

/// 256 px RGBA PNG written by `packaging/gen-icon.py`.
const PNG: &[u8] = include_bytes!("../../../assets/icon/shift-window.png");

/// Decode the embedded icon to (RGBA bytes, width, height).
fn rgba() -> Option<(Vec<u8>, u32, u32)> {
    let mut reader = png::Decoder::new(std::io::Cursor::new(PNG))
        .read_info()
        .ok()?;
    let mut buf = vec![0; reader.output_buffer_size()?];
    let info = reader.next_frame(&mut buf).ok()?;
    if info.color_type != png::ColorType::Rgba || info.bit_depth != png::BitDepth::Eight {
        return None;
    }
    buf.truncate(info.buffer_size());
    Some((buf, info.width, info.height))
}

/// The window icon; `None` only if the embedded PNG is unusable.
pub fn window_icon() -> Option<winit::window::Icon> {
    let (rgba, w, h) = rgba()?;
    winit::window::Icon::from_rgba(rgba, w, h).ok()
}

/// Show the icon in the Dock for an unbundled run (`cargo run`). Inside
/// `Shift.app` the bundle's `.icns` is already used, so this does nothing.
#[cfg(target_os = "macos")]
pub fn set_dock_icon() {
    use objc2::{AllocAnyThread, MainThreadMarker};
    use objc2_app_kit::{NSApplication, NSImage};
    use objc2_foundation::NSData;

    let bundled = std::env::current_exe()
        .map(|p| p.to_string_lossy().contains(".app/Contents/MacOS/"))
        .unwrap_or(false);
    let Some(mtm) = MainThreadMarker::new() else {
        return;
    };
    if bundled {
        return;
    }
    let data = NSData::with_bytes(PNG);
    if let Some(image) = NSImage::initWithData(NSImage::alloc(), &data) {
        // SAFETY: main thread (checked above); the image is a valid NSImage.
        unsafe { NSApplication::sharedApplication(mtm).setApplicationIconImage(Some(&image)) };
        log::info!("dock icon set (unbundled run)");
    } else {
        log::warn!("dock icon: embedded PNG rejected by NSImage");
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn embedded_icon_decodes_to_square_rgba() {
        let (rgba, w, h) = super::rgba().expect("icon decodes");
        assert_eq!((w, h), (256, 256));
        assert_eq!(rgba.len(), 256 * 256 * 4);
        assert!(super::window_icon().is_some());
    }
}
